def test_hypothesis_color_change(input_objects, output_objects):
    input_colors = [obj['colors'][0] for obj in input_objects]
    output_colors = [obj['colors'][0] for obj in output_objects]
    expected_colors = [2, 3, 4]
    return sorted(output_colors) == sorted(expected_colors) and all(color == 5 for color in input_colors)

def test_hypothesis_geometry_change(input_objects, output_objects):
    input_shapes = [obj['shape'] for obj in input_objects]
    output_shapes = [obj['shape'] for obj in output_objects]
    return all(shape == 'irregular shape' for shape in input_shapes) and all(shape == 'filled rectangle' for shape in output_shapes)

def test_hypothesis_number_change(output_objects):
    output_colors = set(obj['colors'][0] for obj in output_objects)
    return len(output_colors) == 3 and 5 not in output_colors

def test_hypothesis_object_modification(input_objects, output_objects):
    for input_obj, output_obj in zip(input_objects, output_objects):
        if input_obj['position'] != output_obj['position']:
            return False
        if input_obj['colors'][0] == output_obj['colors'][0]:
            return False
    return True

def test_hypothesis_commonsense(input_grid, output_grid):
    for i in range(len(input_grid)):
        for j in range(len(input_grid[i])):
            if input_grid[i][j] == 5 and output_grid[i][j] not in [2, 3, 4, 0]:
                return False
    return True
